#!/usr/bin/env bash
# Idempotent source fixes so the plugin builds from a plain git checkout in CI.
#
# 1) udis86/Makefile.am lists subdirs (scripts, udcli, docs, tests) whose
#    Makefiles are never generated by the top-level configure.ac, so `make`
#    dies with "No rule to make target 'all'". Only libudis86 is needed.
# 2) udis86/libudis86/Makefile.am uses @PYTHON@ (never substituted) and
#    paths relative to the udis86 dir (it is not the top source dir here).
# 3) udis86 scripts are python2 era: integer division became float in python3,
#    producing float opcode keys -> "%02x" % k raises TypeError.
# 4) udis86 expects a config.h from its own autoconf, which is never run.
# 5) udis86 must be linked statically; a shipped libaudit_plugin.so that needs
#    libudis86.so.0 cannot be dropped into a MySQL plugin dir.
# 6) MySQL 8.4 headers require C++20; the plugin's configure.ac hard-codes
#    CXXFLAGS without -std.
# 7) MySQL >= 8.4 moved binlog event headers to <src>/libs.
set -euo pipefail
cd "$(dirname "$0")/.."

MYSQL_CXX_STD="${MYSQL_CXX_STD:-c++20}"
DROP_WERROR="${DROP_WERROR:-0}"

python3 - "$MYSQL_CXX_STD" "$DROP_WERROR" <<'PY'
import re, sys, pathlib

cxx_std, drop_werror = sys.argv[1], sys.argv[2] == "1"

# --- 1) udis86 subdirs
p = pathlib.Path("udis86/Makefile.am")
s = p.read_text()
s = re.sub(r"^SUBDIRS\s*=.*$", "SUBDIRS = libudis86", s, flags=re.M)
p.write_text(s)

# --- 2) + 5) udis86 lib makefile
p = pathlib.Path("udis86/libudis86/Makefile.am")
s = p.read_text()
if re.search(r"^PYTHON\s*=", s, flags=re.M):
    s = re.sub(r"^PYTHON\s*=.*$", "PYTHON = python3", s, flags=re.M)
else:
    s = "PYTHON = python3\n" + s
if re.search(r"^OPTABLE\s*=", s, flags=re.M):
    s = re.sub(r"^OPTABLE\s*=.*$", "OPTABLE = $(srcdir)/../docs/x86/optable.xml", s, flags=re.M)
s = s.replace("$(top_srcdir)/scripts/ud_itab.py", "$(srcdir)/../scripts/ud_itab.py")
s = s.replace("$(top_srcdir)/scripts/ud_opcode.py", "$(srcdir)/../scripts/ud_opcode.py")

# udis86 must end up inside the plugin .so, not as a separate libudis86.so.0
# that nobody would have in a MySQL plugin dir. A convenience (noinst) libtool
# library is only ever built as a static archive and gets linked in directly.
s = re.sub(r"^lib_LTLIBRARIES\s*=\s*libudis86\.la", "noinst_LTLIBRARIES = libudis86.la", s, flags=re.M)
# keep the version-info/Windows LDFLAGS harmless for a static archive
s = re.sub(
    r"if TARGET_WINDOWS\nlibudis86_la_LDFLAGS\s*=.*?\nendif\n",
    "",
    s,
    flags=re.S,
)
p.write_text(s)

# --- 3) python3 integer division in udis86 generators
p = pathlib.Path("udis86/scripts/ud_opcode.py")
s = p.read_text()
s = s.replace("(int(v) / 32)", "(int(v) // 32)")
s = s.replace("((int(v, 16) & 0xf) + 1) / 2)", "((int(v, 16) & 0xf) + 1) // 2)")
p.write_text(s)

# --- 4) minimal udis86 config.h (udint.h includes <config.h>)
pathlib.Path("udis86/libudis86/config.h").write_text(
    "/* generated for the mysql-audit build */\n"
    "#ifndef UD_CONFIG_H\n#define UD_CONFIG_H\n"
    "#define HAVE_ASSERT_H 1\n#define HAVE_STRING_H 1\n"
    "#endif\n"
)

# --- 6) C++ standard + optional -Werror removal
p = pathlib.Path("configure.ac")
s = p.read_text()
s = re.sub(
    r'^CXXFLAGS=.*$',
    'CXXFLAGS="-std=%s -fno-implicit-templates -fno-strict-aliasing -fPIC"' % cxx_std,
    s, flags=re.M,
)
if drop_werror:
    s = s.replace('CPPFLAGS="$CPPFLAGS -Werror -Wall"', 'CPPFLAGS="$CPPFLAGS -Wall"')
p.write_text(s)

# --- 7) MySQL >= 8.4 moved binlog event headers to <src>/libs
p = pathlib.Path("config/ac_mysql.m4")
s = p.read_text()
if "-I$withval/libs" not in s:
    s = s.replace('MYSQL_INC="-I$withval/sql', 'MYSQL_INC="-I$withval/sql -I$withval/libs')
p.write_text(s)

# --- 8) MySQL plugin service pointers must be *defined* by the plugin
# MySQL's loader walks its service table (sql/sql_plugin_services.h) and for
# each entry does:
#     sym = dlsym(handle, name);
#     ver = (uint)(intptr)*sym;   // reads the version the plugin declared
#     *(void **)sym = service;    // then patches in the real implementation
# The plugin therefore has to export the variable *initialised to its version*
# (see libservices/thd_alloc_service.c). service_thd_alloc.h only declares it,
# and with -fno-common (GCC >= 10) a tentative definition no longer emits a
# symbol, so the .so fails to load with "undefined symbol: thd_alloc_service".
p = pathlib.Path("src/audit_plugin.cc")
s = p.read_text()
anchor = '#include "md5.h"\n#endif\n'
defn = anchor + '''
#if MYSQL_VERSION_ID >= 50600 && !defined(MARIADB_BASE_VERSION)
#include <service_versions.h>
// mysqld reads the service versions out of these pointers before overwriting
// them with the real implementation, so the initial value must be the
// version constant (this mirrors libservices/thd_alloc_service.c).
extern "C" struct thd_alloc_service_st *thd_alloc_service =
    (struct thd_alloc_service_st *)(intptr_t)VERSION_thd_alloc;
#endif
'''
if "VERSION_thd_alloc" not in s:
    if anchor not in s:
        raise SystemExit("anchor for md5.h not found in audit_plugin.cc")
    s = s.replace(anchor, defn, 1)
p.write_text(s)
PY

echo "--- patched ---"
grep -n '^SUBDIRS' udis86/Makefile.am
grep -nE '^PYTHON|^OPTABLE|^libudis86_la_LDFLAGS' udis86/libudis86/Makefile.am
grep -n '^CXXFLAGS' configure.ac
grep -c 'Werror' configure.ac || true
grep -n 'MYSQL_INC=' config/ac_mysql.m4
